// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsFile 是每仓库阈值配置文件的路径，相对仓库根目录；
// 内容形如 {"shanghai": 20}。文件不存在或某仓库没配时回退到
// DefaultLowStockThreshold。
const thresholdsFile = "inventory/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 配置来源是 thresholdsFile；读取失败、解析失败或该仓库没配，都回退到
// DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, err := loadThresholds()
	if err != nil {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取 thresholdsFile。文件缺失或内容不是
// map[string]int 时返回错误，由调用方回退到默认值。
func loadThresholds() (map[string]int, error) {
	data, err := os.ReadFile(thresholdsFile)
	if err != nil {
		return nil, err
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, err
	}
	return thresholds, nil
}
```

