// LowStockThreshold 返回这个仓库的低库存阈值。
//
// 配置来自 thresholdsFile：路径相对**进程工作目录**（约定为仓库根目录）解析，
// 所以进程需在仓库根目录启动，否则会静默回退到默认值。文件不存在、读不动、
// 解析失败，或该仓库没配，都回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	return thresholdFor(loadThresholds(), warehouse)
}

// thresholdFor 从已读出的配置里取该仓库阈值；没配则回退默认值。
func thresholdFor(thresholds map[string]int, warehouse string) int {
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// loadThresholds 读取 thresholdsFile，返回每仓库阈值。
// 文件缺失、读不动或内容不是 map[string]int 都返回 nil，调用方据此回退默认值。
func loadThresholds() map[string]int {
	data, err := os.ReadFile(thresholdsFile)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	return quantity < LowStockThreshold(warehouse)
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库，按名字排序。
func LowStockWarehouses(stock map[string]int) []string {
	thresholds := loadThresholds() // 整批只读一次配置
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if quantity < thresholdFor(thresholds, warehouse) {
			low = append(low, warehouse)
		}
	}
	sort.Strings(low)
	return low
}
